WITH enriched AS (SELECT *, LAG(sqft) OVER (PARTITION BY city, region ORDER BY opened_date, id) prev_sqft, LEAD(sqft) OVER (PARTITION BY city, region ORDER BY opened_date, id) next_sqft, ROW_NUMBER() OVER (PARTITION BY city, region ORDER BY opened_date, id) row_seq, AVG(sqft) OVER (PARTITION BY region, city ORDER BY sqft, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) sqft_avg_6 FROM stores WHERE city IN ('New York', 'Chiang Mai')) SELECT id, store_name, city, opened_date, sqft, row_seq, sqft_avg_6, CASE WHEN store_name RLIKE '^(Downtown Express|Old Town)$' THEN 'OTHER_ZONE' WHEN store_name RLIKE '^(Siam Flagship|Airport Kiosk)$' THEN 'GROUP_B' ELSE 'CORE' END AS store_name_zone FROM enriched ORDER BY id DESC, store_name_zone DESC LIMIT 5;
